#!/usr/bin/env python3
import os, pty, sys, fcntl, termios, struct, select
BIN='/tmp/ref/crowbook'
def runpty(args, cwd=None, env=None, cols=80, rows=24):
    pid, fd = pty.fork()
    if pid==0:
        if cwd: os.chdir(cwd)
        e=dict(os.environ)
        e.pop('LANG',None); e.pop('LC_ALL',None); e.pop('LANGUAGE',None)
        e.setdefault('TERM','xterm-256color')
        e['COLUMNS']=str(cols); e['LINES']=str(rows)
        if env: e.update(env)
        os.execve(BIN, ['crowbook']+args, e)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    out=b''
    while True:
        try:
            r,_,_=select.select([fd],[],[],5)
            if not r: break
            c=os.read(fd,65536)
        except OSError:
            break
        if not c: break
        out+=c
    _,st=os.waitpid(pid,0)
    return out, os.waitstatus_to_exitcode(st)
if __name__=='__main__':
    o,rc=runpty(sys.argv[1:])
    print('exit=%d'%rc)
    print(repr(o))

